  // ── Income and Budget tab ──
  'budget.intro':              { en: 'Track today\'s budget in today\'s dollars, and see it projected forward using the Retirement Income tab · Categories adapted from the Government of Canada\'s <a href="https://itools-ioutils.fcac-acfc.gc.ca/BP-PB/budget-planner-tool" target="_blank" rel="noopener" style="color:#93c5fd;">FCAC Budget Planner</a>', fr: 'Suivez votre budget d’aujourd’hui en dollars actuels, et voyez-le projeté dans le futur grâce à l’onglet Revenu de retraite · Catégories adaptées de l’outil <a href="https://itools-ioutils.fcac-acfc.gc.ca/BP-PB/budget-planner-tool" target="_blank" rel="noopener" style="color:#93c5fd;">Planificateur budgétaire de l’ACFC</a> du gouvernement du Canada' },
  // N20 (2026-09-20): the essential-spending floor.
  'budget.essential.toggle': { en: 'Essential \u2014 must be covered', fr: 'Essentiel \u2014 doit \u00eatre couvert' },
  'budget.targetNote': { en: 'This is the real number that decides whether a retirement year shows a surplus or a shortfall — separate from the "Target Income" figure on the Retirement Income tab, which only sizes registered (LIF/RRIF) withdrawals and defaults to flat example amounts by age.', fr: 'C’est ce chiffre réel qui détermine si une année de retraite affiche un surplus ou un manque à gagner — distinct du « Revenu cible » de l’onglet Revenu de retraite, qui ne fait que dimensionner les retraits enregistrés (FRV/FERR) et utilise par défaut des montants d’exemple fixes selon l’âge.' },
  'budget.subtab.overview':    { en: 'Overview', fr: 'Aperçu' },
