  'acc.db.bridgeNote': { en: 'Bridge benefit (optional) — an extra amount paid on top of the above until a set age, then it stops (leave blank if none)', fr: 'Rente de raccordement (facultative) — un montant supplémentaire versé en plus de ce qui précède jusqu’à un âge déterminé, puis qui cesse (laisser vide si aucune)' },

