  'ret.popover.targetIncome.note': { en: 'Sizes your registered (LIF/RRIF) withdrawal only — your real Budget (Income and Budget tab) is what decides surplus vs. shortfall.', fr: 'Détermine uniquement votre retrait enregistré (FRV/FERR) — votre Budget réel (onglet Revenus et budget) décide du surplus ou du manque à gagner.' },
  'ret.popover.copyUntilAge':  { en: 'Copy until age', fr: 'Copier jusqu’à l’âge' },
