  'ret.subtab.household': { en: '👫 Household', fr: '👫 Ménage' },
  'profile.hh.title': { en: '👫 Household (spouse / partner)', fr: '👫 Ménage (conjoint·e)' },
  'profile.hh.help': { en: 'Optional. Adds a second person with their own pensions and accounts, simulated alongside your plan and merged year by year — with pension income splitting, per-person OAS clawback and a survivor pension. Results appear on the Retirement Income tab\'s Household sub-tab (Resident mode only). Amounts are today\'s dollars unless noted.', fr: 'Facultatif. Ajoute une deuxième personne avec ses propres pensions et comptes, simulée en parallèle de votre plan et fusionnée année par année — avec fractionnement du revenu de pension, récupération de la SV par personne et pension de survivant. Les résultats apparaissent dans le sous-onglet Ménage de l\'onglet Revenu de retraite (mode Résident seulement). Montants en dollars d\'aujourd\'hui sauf indication contraire.' },
  'profile.hh.enable': { en: 'Plan as a couple', fr: 'Planifier en couple' },
