  'profile.hh.contribNote': { en: 'Balances grow at the retirement growth rate (Non-Registered at its own rate) until the Start Age, with the contributions added each year.', fr: 'Les soldes croissent au taux de croissance de la retraite (non enregistré à son propre taux) jusqu\'à l\'âge de départ, les cotisations s\'ajoutant chaque année.' },
  'profile.hh.name': { en: 'Spouse\'s name', fr: 'Nom du conjoint·e' },
