  'profile.hh.deathAge.title': { en: "The age each of you is assumed to die at — separate from the horizon the projection runs to. Blank uses life expectancy from that person's own current age. The survivor keeps going to their own horizon.", fr: 'L’âge auquel chacun de vous est supposé décéder — distinct de l’horizon de la projection. Laissé vide, l’espérance de vie calculée depuis l’âge actuel de cette personne est utilisée. Le survivant continue jusqu’à son propre horizon.' },
  'profile.hh.survivorRatio': { en: "Survivor spending (% of couple's)", fr: 'Dépenses du survivant (% du couple)' },
  'profile.hh.survivorRatio.title': { en: 'What the survivor spends, as a share of what the two of you spent together — typically 60-70%, not the 50% share they carried while both were alive. One person still heats the whole house.', fr: 'Ce que dépense le survivant, en proportion de ce que vous dépensiez à deux — généralement 60 à 70 %, et non la part de 50 % qu’il assumait du vivant des deux. Une seule personne chauffe quand même toute la maison.' },
  'profile.hh.survivorPct': { en: 'Survivor pension (% of DB)', fr: 'Pension de survivant (% de la PD)' },
  'profile.hh.lif': { en: 'LIF / locked-in ($)', fr: 'FRV / immobilisé ($)' },
