  'profile.hh.rrspAnnual': { en: 'RRSP contribution ($/yr)', fr: 'Cotisation REER ($/an)' },
  'profile.hh.tfsa': { en: 'TFSA ($)', fr: 'CELI ($)' },
  'profile.hh.tfsaAnnual': { en: 'TFSA contribution ($/yr)', fr: 'Cotisation CELI ($/an)' },
  'profile.hh.nonreg': { en: 'Non-Registered ($)', fr: 'Non enregistré ($)' },
  'profile.hh.qppEligible': { en: 'Contributed to QPP/CPP', fr: 'A cotisé au RRQ/RPC' },
  'profile.hh.oasEligible': { en: 'Eligible for OAS', fr: 'Admissible à la SV' },
  'profile.hh.split': { en: 'Pension income splitting', fr: 'Fractionnement du revenu de pension' },
  'profile.hh.split.title': { en: 'Each year both of you are retired, up to 50% of the higher earner\'s eligible pension income (DB at any age, RRIF/LIF from 65; Quebec: 65+ for the provincial return) is moved to the lower earner when that lowers the couple\'s combined tax + OAS clawback.', fr: 'Chaque année où vous êtes tous deux à la retraite, jusqu\'à 50 % du revenu de pension admissible du plus haut revenu (PD à tout âge, FERR/FRV dès 65 ans; Québec : 65 ans et plus pour la déclaration provinciale) est transféré au plus bas revenu lorsque cela réduit l\'impôt combiné + la récupération de la SV du couple.' },
  'profile.hh.note': { en: 'The spouse funds their share of the household Budget and Target from their own accounts; the survivor keeps the survivor pension and inherits the other\'s balances at the horizon. Employment income before the spouse\'s Start Age is not modelled.', fr: 'Le conjoint·e finance sa part du Budget et de la Cible du ménage à partir de ses propres comptes; le survivant conserve la pension de survivant et hérite des soldes de l\'autre à l\'horizon. Le revenu d\'emploi avant l\'âge de départ du conjoint·e n\'est pas modélisé.' },
  'hh.you': { en: 'You', fr: 'Vous' },
  'hh.shareChip': { en: 'Couple mode — your plan funds {pct}% of the household Budget; {spouse} funds the rest (see the Household sub-tab)', fr: 'Mode couple — votre plan finance {pct} % du Budget du ménage; {spouse} finance le reste (voir le sous-onglet Ménage)' },
  'hh.spouse': { en: 'Spouse', fr: 'Conjoint·e' },
  'hh.desc': { en: 'Your plan and {spouse}\'s, simulated separately from each person\'s own accounts and pensions, then merged by calendar year: pension income splitting where it lowers the couple\'s combined tax and OAS clawback, per-person OAS clawback, and a survivor pension plus inherited balances after the first horizon. Each person funds their share of the household Budget.', fr: 'Votre plan et celui de {spouse}, simulés séparément à partir des comptes et pensions de chacun, puis fusionnés par année civile : fractionnement du revenu de pension là où il réduit l\'impôt combiné et la récupération de la SV du couple, récupération de la SV par personne, et pension de survivant plus soldes hérités après le premier horizon. Chaque personne finance sa part du Budget du ménage.' },
  'hh.notice.survivor': { en: '{who} is assumed to die at {age}. {surv} carries on to their own horizon, inheriting the accounts, and spends {pct}% of what the two of you spent together — with the DB survivor pension, the CPP/QPP survivor\'s pension and, between 60 and 64, the OAS Allowance for the Survivor added to their income.', fr: '{who} est supposé·e décéder à {age} ans. {surv} poursuit jusqu’à son propre horizon, hérite des comptes et dépense {pct} % de ce que vous dépensiez à deux — avec la rente de conjoint survivant du régime PD, la rente de conjoint survivant du RPC/RRQ et, entre 60 et 64 ans, l’Allocation au survivant de la SV ajoutées à ses revenus.' },
  'hh.notice.spouseRetired': { en: 'Your spouse retired at {ret} and is {cur} — their projection restarts at {cur}, with the benefits they already started still in payment.', fr: 'Votre conjoint·e a pris sa retraite à {ret} et a {cur} ans — sa projection redémarre à {cur}, les prestations déjà commencées restant en paiement.' },
  'hh.notice.retBeforeCur': { en: 'The spouse\'s Start Age ({ret}) is before their current age ({cur}) — fix it on the Profile tab.', fr: 'L\'âge de départ du conjoint·e ({ret}) précède son âge actuel ({cur}) — corrigez-le dans l\'onglet Profil.' },
  'hh.notice.noRows': { en: 'The spouse\'s plan could not be simulated (Start Age past the horizon?).', fr: 'Le plan du conjoint·e n\'a pas pu être simulé (âge de départ au-delà de l\'horizon?).' },
  'hh.notice.differentYears': { en: 'Note: you and {spouse} retire in different calendar years; a person who has not retired yet contributes nothing to the household figures for that year (employment income is not modelled).', fr: 'Note : vous et {spouse} prenez votre retraite des années civiles différentes; une personne non encore retraitée ne contribue pas aux chiffres du ménage pour cette année (le revenu d\'emploi n\'est pas modélisé).' },
  'hh.summary.netEstate': { en: 'Household Net Estate — {year} (after death tax)', fr: 'Succession nette du ménage — {year} (après impôt au décès)' },
  'hh.summary.survivor': { en: 'Survivor: {name} (to age {age})', fr: 'Survivant : {name} (jusqu\'à {age} ans)' },
  'hh.summary.sameHorizon': { en: 'Both horizons fall in the same year', fr: 'Les deux horizons tombent la même année' },
