  'hh.summary.splitSaving': { en: 'Saved by pension splitting', fr: 'Économie du fractionnement' },
  'hh.summary.splitSaving.note': { en: 'lifetime, vs. no splitting', fr: 'à vie, c. sans fractionnement' },
  'hh.summary.firstShortfall': { en: 'First household shortfall', fr: 'Premier déficit du ménage' },
  'hh.summary.shortfallAt': { en: '{year} (age {ageP})', fr: '{year} ({ageP} ans)' },
  'hh.summary.guaranteed': { en: 'Guaranteed household pensions @{age}', fr: 'Pensions garanties du ménage à {age} ans' },
  'hh.summary.guaranteed.note': { en: 'DB + QPP/CPP + OAS, both retired, first year', fr: 'PD + RRQ/RPC + SV, tous deux retraités, première année' },
  'hh.summary.deterministicNote': { en: 'Deterministic, like the Plan sub-tab: flat Growth / CPI rates, each person\'s withdrawals sized to their own share of the Budget. The splitting saving is reported and added to cash flow, not reinvested. See the Help tab for the full list of assumptions.', fr: 'Déterministe, comme le sous-onglet Plan : taux de croissance / IPC fixes, retraits de chacun dimensionnés selon sa part du Budget. L\'économie du fractionnement est indiquée et ajoutée au flux de trésorerie, non réinvestie. Voir l\'onglet Aide pour la liste complète des hypothèses.' },
