  'ret.table.budgetTitle': { en: "Click to view this year's budget on the Income and Budget tab · hover for the inflation assumption behind it", fr: 'Cliquez pour voir le budget de cette année dans l’onglet Revenus et budget · survolez pour voir l’hypothèse d’inflation utilisée' },
  'ret.table.noPayroll': { en: 'No payroll deductions from your Start Age on — retirement income (DB/CPP/RRIF/etc.) has none.', fr: 'Aucune retenue sur la paie à partir de votre âge de début — le revenu de retraite (pension PD/RPC/FERR, etc.) n’en comporte aucune.' },
