  'ret.footer.nonresHalfDesc': { en: 'Non-Resident + 50% LIF→RRIF ({amt1}→{amt2} by 80, half unlocked yr 1, no lump ever)', fr: 'Non-résident + 50 % FRV→FERR ({amt1}→{amt2} d’ici 80 ans, moitié débloquée l’an 1, jamais de somme forfaitaire)' },
