  'ret.footer.lifHalf': { en: 'LIF: 50% unlocked tax-free to RRIF in yr 1 · remaining 50% capped at the federal maximum thereafter · no lump event', fr: 'FRV : 50 % débloqué sans impôt vers le FERR l’an 1 · le 50 % restant plafonné au maximum fédéral par la suite · aucune somme forfaitaire' },
