  'ret.footer.qppDeferred': { en: '{cq}: delayed to 70 ({amt}/yr nominal, indexed at CPI − 0.15 pp) · OAS: at 65 (~{oasAmt}/yr nominal, indexed at CPI − 0.15 pp) ·', fr: '{cq} : reporté à 70 ans ({amt}/an nominal, indexé à l’IPC − 0,15 pt) · SV : à 65 ans (~{oasAmt}/an nominal, indexée à l’IPC − 0,15 pt) ·' },
  'ret.footer.dbLine': { en: 'DB: {base} flat → +1%/yr ages 65–74 → frozen {frozen} from 75 ·', fr: 'Pension PD : {base} fixe → +1 %/an de 65 à 74 ans → gelée à {frozen} dès 75 ans ·' },
