  // ── Optimizer / Sustainable Spend cards ──
  'ret.sanity.zeroSpend': { en: 'Actual spend is $0 across every year despite a real projected portfolio — the Budget tab may not be filled in yet, so this live simulation likely understates real spending.', fr: 'Les dépenses réelles sont de 0 $ chaque année malgré un portefeuille réellement projeté — l’onglet Budget n’a peut-être pas encore été rempli, donc cette simulation en direct sous-estime probablement les dépenses réelles.' },
  'ret.sustain.active': { en: 'Sustainable Spend Scenario ACTIVE', fr: 'Scénario de dépenses soutenables ACTIF' },
  'ret.sustain.activeNote': { en: ' — overall Budget spending scaled to {pct}% for this simulation (Debt repayment excluded, real Budget-tab numbers untouched).', fr: ' — dépenses budgétaires globales ramenées à {pct} % pour cette simulation (remboursement de dettes exclu, chiffres réels de l’onglet Budget non modifiés).' },
  'ret.sustain.deactivate': { en: 'Deactivate', fr: 'Désactiver' },
  'ret.sustain.summaryDefault': { en: 'Find the highest overall Budget-spending level (a uniform scale on your current Budget tab, Debt repayment excluded) that still passes a deterministic + Reverse Sequence Risk viability check, every year through the end of your horizon.', fr: 'Trouve le niveau de dépenses budgétaires global le plus élevé (une échelle uniforme sur votre onglet Budget actuel, remboursement de dettes exclu) qui réussit encore un test de viabilité déterministe + Risque de séquence inversée, chaque année jusqu’à la fin de votre horizon.' },
  'ret.sustain.calculating': { en: 'Calculating… (running deterministic + reverse-sequence-risk checks across a range of spending levels)', fr: 'Calcul en cours… (exécution de tests déterministes + de risque de séquence inversée sur une plage de niveaux de dépenses)' },
  'ret.sustain.noLiveSim': { en: 'No live simulation available yet.', fr: 'Aucune simulation en direct disponible pour l’instant.' },
  'ret.sustain.errorRunning': { en: 'Error running test: {msg}', fr: 'Erreur lors de l’exécution du test : {msg}' },
  'ret.sustain.headline.cappedAtMax': { en: 'Even at {pct}% of your current Budget spending (the highest level this search checks), your plan stays fully funded through every deterministic and reverse-sequence-risk check — you may be able to spend meaningfully more than your current Budget plans for.', fr: 'Même à {pct} % de vos dépenses budgétaires actuelles (le niveau le plus élevé vérifié par cette recherche), votre plan reste entièrement financé à tous les tests déterministes et de risque de séquence inversée — vous pourriez dépenser sensiblement plus que ce que prévoit votre budget actuel.' },
  'ret.sustain.headline.notViableAtMin': { en: "Your plan doesn't pass a fully-funded check even at {pct}% of your current Budget spending (the lowest level this search checks) — the shortfall isn't something a lower spending level alone can fix.", fr: 'Votre plan ne réussit pas le test de financement complet même à {pct} % de vos dépenses budgétaires actuelles (le niveau le plus bas vérifié par cette recherche) — le manque à gagner ne peut être corrigé par une simple réduction des dépenses.' },
  'ret.sustain.headline.viableAt1': { en: 'Your current Budget spending is already viable. Sustainable ceiling found: <strong>{pct}% of your current Budget spending</strong> ({amt}/yr at the start of retirement) — the highest level that still passes every check.', fr: 'Vos dépenses budgétaires actuelles sont déjà viables. Plafond soutenable trouvé : <strong>{pct} % de vos dépenses budgétaires actuelles</strong> ({amt}/an au début de la retraite) — le niveau le plus élevé qui réussit encore tous les tests.' },
  'ret.sustain.headline.notViable': { en: 'Your current Budget spending is <strong>not</strong> fully viable as entered. Sustainable level found: <strong>{pct}% of your current Budget spending</strong> ({amt}/yr at the start of retirement) — the highest level that passes every check.', fr: 'Vos dépenses budgétaires actuelles ne sont <strong>pas</strong> entièrement viables telles qu’entrées. Niveau soutenable trouvé : <strong>{pct} % de vos dépenses budgétaires actuelles</strong> ({amt}/an au début de la retraite) — le niveau le plus élevé qui réussit tous les tests.' },
  'ret.sustain.estateLine': { en: 'Net Estate at this level: {amt} (vs. {curAmt} at your current Budget spending{note}).', fr: 'Succession nette à ce niveau : {amt} (c. {curAmt} à vos dépenses budgétaires actuelles{note}).' },
  'ret.sustain.estateLine.notFullyFunded': { en: ' -- which does not fully fund the plan', fr: ' -- ce qui ne finance pas entièrement le plan' },
  'ret.sustain.depletedNote': { en: 'At this level, your invested accounts (LIF/RRIF/TFSA/Non-Reg/Emergency Fund) reach $0 by age {age} -- spending after that is fully covered by pension/QPP/OAS income, not a funding shortfall.', fr: 'À ce niveau, vos comptes investis (FRV/FERR/CELI/non enregistré/fonds d’urgence) atteignent 0 $ à l’âge de {age} ans -- les dépenses après cet âge sont entièrement couvertes par le revenu de pension/RRQ/SV, et non un manque à gagner.' },
  'ret.sustain.activateBtn': { en: 'Activate this rate', fr: 'Activer ce taux' },
  'ret.sustain.shapeLabel': { en: 'Spending shape:', fr: 'Répartition des dépenses :' },
  'ret.sustain.shape.uniform': { en: 'Uniform', fr: 'Uniforme' },
  'ret.sustain.shape.phased.title': { en: 'Applies the found rate at 100% during the Go-Go years, then tapers to 85% (Slow-Go) and 70% (No-Go) -- same age bands as the phase cards above. A fixed shape, not editable.', fr: 'Applique le taux trouvé à 100 % durant les années Actives, puis le réduit à 85 % (Ralentie) et 70 % (Réduite) -- mêmes tranches d’âge que les cartes de phase ci-dessus. Répartition fixe, non modifiable.' },
  'ret.sustain.activeNote.phased': { en: ' — overall Budget spending scaled to {pct}% using a phased {shape} shape (Go-Go {gogoAmt}/yr, Slow-Go {slowgoAmt}/yr, No-Go {nogoAmt}/yr; Debt repayment excluded, real Budget-tab numbers untouched).', fr: ' — dépenses budgétaires globales ramenées à {pct} % selon une répartition progressive {shape} (Active {gogoAmt}/an, Ralentie {slowgoAmt}/an, Réduite {nogoAmt}/an ; remboursement de dettes exclu, chiffres réels de l’onglet Budget non modifiés).' },
  'ret.sustain.phaseBreakdown': { en: 'Phase breakdown: {gogoLabel} {gogoAmt}/yr · {slowgoLabel} {slowgoAmt}/yr · {nogoLabel} {nogoAmt}/yr.', fr: 'Répartition par phase : {gogoLabel} {gogoAmt}/an · {slowgoLabel} {slowgoAmt}/an · {nogoLabel} {nogoAmt}/an.' },

