  // ── Help tab (French Translation Phase 4) ──
  'help.header.title': { en: '❓ Help', fr: '❓ Aide' },
  'help.header.sub': { en: 'How this planner works, section by section -- the rules, formulas, and defaults behind every number it shows you.', fr: 'Comment fonctionne ce planificateur, section par section -- les règles, les formules et les valeurs par défaut derrière chaque chiffre qu’il affiche.' },
